#!/usr/bin/env python3
"""
Gold Price Dynamics Report Generator
Analyzes gold price data from 2000-2025 and produces a comprehensive HTML report.
"""

import pandas as pd
import numpy as np
from datetime import datetime
import json

# Load and parse data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%d-%m-%y')

# Handle 2-digit year: 00-68 -> 2000-2068, 69-99 -> 1969-1999
# But since our data is 2000-2025, all should be 2000+
df.loc[df['Date'].dt.year > 2050, 'Date'] = df.loc[df['Date'].dt.year > 2050, 'Date'].apply(
    lambda x: x.replace(year=x.year - 100)
)

df = df.sort_values('Date').reset_index(drop=True)

# Round prices to 2 decimal places
for col in ['Open', 'High', 'Low', 'Close']:
    df[col] = df[col].round(2)

# Calculate daily log returns
df['LogReturn'] = np.log(df['Close'] / df['Close'].shift(1))

# Basic info
start_date = df['Date'].min()
end_date = df['Date'].max()
n_days = len(df)

print(f"Data loaded: {start_date.strftime('%Y-%m-%d')} to {end_date.strftime('%Y-%m-%d')}")
print(f"Total trading days: {n_days}")

# ============================================
# KPI CALCULATIONS
# ============================================

# 1. Annualized Return (CAGR)
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = (last_close / first_close) ** (1/years) - 1

# 2. Annualized Volatility (std of log returns, annualized)
daily_vol = df['LogReturn'].std()
annualized_vol = daily_vol * np.sqrt(252)

# 3. Maximum Drawdown
cumulative = (1 + df['LogReturn'].fillna(0)).cumprod()
rolling_max = cumulative.cummax()
drawdown = (cumulative - rolling_max) / rolling_max
max_drawdown = drawdown.min()

# 4. Average Daily Volume (excluding early zero-volume period)
# Flag volume issues in early years
df['VolumeReliable'] = df['Volume'] > 0
reliable_volume_mean = df[df['Volume'] > 0]['Volume'].mean()

# 5. Sharpe-like Ratio (return / volatility, assuming rf=0)
sharpe_like = cagr / annualized_vol

print(f"\n=== KEY KPIs ===")
print(f"Annualized Return: {cagr:.2%}")
print(f"Annualized Volatility: {annualized_vol:.2%}")
print(f"Maximum Drawdown: {max_drawdown:.2%}")
print(f"Average Daily Volume (reliable): {reliable_volume_mean:,.0f}")
print(f"Sharpe-Like Ratio: {sharpe_like:.2f}")

# ============================================
# VOLATILITY REGIME DETECTION
# ============================================

# Calculate rolling volatility (20-day and 60-day)
df['RollingVol20'] = df['LogReturn'].rolling(window=20).std() * np.sqrt(252)
df['RollingVol60'] = df['LogReturn'].rolling(window=60).std() * np.sqrt(252)

# Define regimes based on percentiles of rolling volatility
vol_percentiles = df['RollingVol60'].dropna().quantile([0.33, 0.66])
low_vol_threshold = vol_percentiles[0.33]
high_vol_threshold = vol_percentiles[0.66]

def classify_regime(vol):
    if pd.isna(vol):
        return 'unknown'
    elif vol < low_vol_threshold:
        return 'low'
    elif vol > high_vol_threshold:
        return 'high'
    else:
        return 'medium'

df['VolRegime'] = df['RollingVol60'].apply(classify_regime)

# Identify crisis periods (extremely high volatility)
crisis_threshold = df['RollingVol60'].quantile(0.90)
df['Crisis'] = df['RollingVol60'] > crisis_threshold

# Crisis periods identified
crisis_periods = df[df['Crisis']]['Date'].tolist()
print(f"\nCrisis periods identified: {len(crisis_periods)} days with >90th percentile volatility")

# ============================================
# SEASONAL PATTERNS
# ============================================

df['Month'] = df['Date'].dt.month
df['DayOfWeek'] = df['Date'].dt.dayofweek  # 0=Monday

# Monthly returns
monthly_returns = df.groupby('Month')['LogReturn'].agg(['mean', 'std', 'count'])
monthly_returns['annualized'] = monthly_returns['mean'] * 12
monthly_returns['t_stat'] = monthly_returns['mean'] / (monthly_returns['std'] / np.sqrt(monthly_returns['count']))
monthly_returns['p_value'] = 2 * (1 - np.abs(monthly_t_cdf(monthly_returns['t_stat'].values, monthly_returns['count'] - 1)))

from scipy import stats
monthly_t_cdf = lambda t, df: stats.t.cdf(t, df)

# Day of week analysis
dow_returns = df.groupby('DayOfWeek')['LogReturn'].agg(['mean', 'std', 'count'])
dow_returns['t_stat'] = dow_returns['mean'] / (dow_returns['std'] / np.sqrt(dow_returns['count']))

# ============================================
# RETURN DISTRIBUTION
# ============================================

returns_clean = df['LogReturn'].dropna()

# Stats
skewness = stats.skew(returns_clean)
kurtosis = stats.kurtosis(returns_clean)  # Excess kurtosis

# Percentiles
percentiles = [1, 5, 10, 25, 50, 75, 90, 95, 99]
return_percentiles = np.percentile(returns_clean, percentiles)

# VaR and CVaR (Historical)
var_95 = np.percentile(returns_clean, 5)
cvar_95 = returns_clean[returns_clean <= var_95].mean()

# ============================================
# MOMENTUM DYNAMICS
# ============================================

# Moving averages
df['MA20'] = df['Close'].rolling(20).mean()
df['MA50'] = df['Close'].rolling(50).mean()
df['MA200'] = df['Close'].rolling(200).mean()

# Rate of change (1M, 3M, 6M, 12M)
df['ROC_1M'] = df['Close'].pct_change(21)  # ~21 trading days per month
df['ROC_3M'] = df['Close'].pct_change(63)
df['ROC_6M'] = df['Close'].pct_change(126)
df['ROC_12M'] = df['Close'].pct_change(252)

# Crossover signals (simplified)
df['MA20_above_MA50'] = df['MA20'] > df['MA50']

# ============================================
# VOLUME ANALYSIS
# ============================================

# Volume thresholds
vol_percentiles_data = df[df['Volume'] > 0]['Volume'].quantile([0.25, 0.5, 0.75, 0.95])
high_vol_threshold_volume = vol_percentiles_data[0.95]

# Relate volume to price changes
df['PriceChange'] = df['Close'].pct_change()
df['AbsPriceChange'] = df['PriceChange'].abs()
df['HighVolume'] = df['Volume'] > vol_percentiles_data[0.75]

# ============================================
# GENERATE VISUALIZATIONS (SVG)
# ============================================

import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from io import StringIO
import base64

def fig_to_svg(fig):
    buf = StringIO()
    fig.savefig(buf, format='svg', bbox_inches='tight', dpi=150)
    buf.seek(0)
    return buf.read()

def fig_to_base64_png(fig):
    buf = StringIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode()

# Color scheme
GOLD = '#FFD700'
DARK_BG = '#1a1a2e'
LIGHT_BG = '#f5f5f5'
BLUE = '#2E86AB'
RED = '#E63946'
GREEN = '#2A9D8F'

plt.style.use('seaborn-v0_8-whitegrid')

# 1. Price Chart with MA
fig1, ax1 = plt.subplots(figsize=(14, 6))
ax1.plot(df['Date'], df['Close'], color=GOLD, linewidth=0.8, label='Close Price', alpha=0.9)
ax1.plot(df['Date'], df['MA50'], color=BLUE, linewidth=1, label='50-day MA', alpha=0.7)
ax1.plot(df['Date'], df['MA200'], color=RED, linewidth=1.2, label='200-day MA', alpha=0.7)
ax1.fill_between(df['Date'], df['Close'].min(), df['Close'], alpha=0.1, color=GOLD)

# Mark crisis periods
crisis_df = df[df['Crisis']]
for idx in crisis_df.index:
    ax1.axvline(df.loc[idx, 'Date'], color='red', alpha=0.15, linewidth=0.5)

ax1.set_title('Gold Price: Long-Term Trend (2000-2025)', fontsize=14, fontweight='bold')
ax1.set_xlabel('Date')
ax1.set_ylabel('Price (USD)')
ax1.legend(loc='upper left')
ax1.set_facecolor(LIGHT_BG)
price_chart_svg = fig_to_svg(fig1)
plt.close(fig1)

# 2. Volatility Regime Chart
fig2, ax2 = plt.subplots(figsize=(14, 5))
colors = {'low': GREEN, 'medium': BLUE, 'high': RED}
for regime in ['low', 'medium', 'high']:
    mask = df['VolRegime'] == regime
    ax2.scatter(df.loc[mask, 'Date'], df.loc[mask, 'RollingVol60'],
                c=colors[regime], s=3, alpha=0.5, label=f'{regime.capitalize()} Vol')

ax2.set_title('Volatility Regime Detection (60-day Rolling, Annualized)', fontsize=14, fontweight='bold')
ax2.set_xlabel('Date')
ax2.set_ylabel('Annualized Volatility')
ax2.legend(markerfirst=False)
ax2.set_facecolor(LIGHT_BG)
vol_chart_svg = fig_to_svg(fig2)
plt.close(fig2)

# 3. Rolling Drawdown
fig3, ax3 = plt.subplots(figsize=(14, 5))
ax3.fill_between(df['Date'], drawdown * 100, 0, color=RED, alpha=0.5)
ax3.plot(df['Date'], drawdown * 100, color=RED, linewidth=0.5)
ax3.set_title('Rolling Drawdown (%)', fontsize=14, fontweight='bold')
ax3.set_xlabel('Date')
ax3.set_ylabel('Drawdown (%)')
ax3.set_facecolor(LIGHT_BG)
drawdown_chart_svg = fig_to_svg(fig3)
plt.close(fig3)

# 4. Monthly Returns Heatmap
fig4, ax4 = plt.subplots(figsize=(12, 6))
monthly_data = df.groupby([df['Date'].dt.year, 'Month'])['LogReturn'].sum().unstack()
monthly_data.index = monthly_data.index.astype(int)
monthly_data.columns = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

im = ax4.imshow(monthly_data.values * 100, cmap='RdYlGn', aspect='auto', vmin=-10, vmax=10)
ax4.set_xticks(range(12))
ax4.set_xticklabels(monthly_data.columns)
ax4.set_yticks(range(len(monthly_data)))
ax4.set_yticklabels(monthly_data.index)
ax4.set_title('Monthly Returns Heatmap (%)', fontsize=14, fontweight='bold')
plt.colorbar(im, ax=ax4, label='Return %')
for i in range(len(monthly_data)):
    for j in range(12):
        val = monthly_data.iloc[i, j] * 100
        if not np.isnan(val):
            ax4.text(j, i, f'{val:.0f}', ha='center', va='center', fontsize=7,
                    color='black' if abs(val) < 5 else 'white')
monthly_heatmap_svg = fig_to_svg(fig4)
plt.close(fig4)

# 5. Return Distribution
fig5, (ax5a, ax5b) = plt.subplots(1, 2, figsize=(14, 5))
# Histogram
n, bins, patches = ax5a.hist(returns_clean * 100, bins=100, density=True, alpha=0.7, color=BLUE)
# Normal overlay
x = np.linspace(returns_clean.min() * 100, returns_clean.max() * 100, 100)
normal_dist = stats.norm.pdf(x, returns_clean.mean() * 100, returns_clean.std() * 100)
ax5a.plot(x, normal_dist, 'r-', linewidth=2, label='Normal Distribution')
ax5a.set_title('Daily Return Distribution', fontsize=14, fontweight='bold')
ax5a.set_xlabel('Daily Return %')
ax5a.set_ylabel('Density')
ax5a.legend()
ax5a.set_facecolor(LIGHT_BG)

# Q-Q plot
stats.probplot(returns_clean, dist="norm", plot=ax5b)
ax5b.set_title('Q-Q Plot (vs Normal)', fontsize=14, fontweight='bold')
ax5b.set_facecolor(LIGHT_BG)
distribution_chart_svg = fig_to_svg(fig5)
plt.close(fig5)

# 6. Seasonal Pattern (Monthly Avg Returns)
fig6, ax6 = plt.subplots(figsize=(12, 5))
month_names = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
monthly_means = df.groupby('Month')['LogReturn'].mean() * 100
colors_bar = [RED if x < 0 else GREEN for x in monthly_means]
bars = ax6.bar(range(1, 13), monthly_means, color=colors_bar, alpha=0.7, edgecolor='black')
ax6.axhline(y=0, color='black', linewidth=0.5)
ax6.set_xticks(range(1, 13))
ax6.set_xticklabels(month_names)
ax6.set_title('Average Daily Returns by Month (%)', fontsize=14, fontweight='bold')
ax6.set_xlabel('Month')
ax6.set_ylabel('Mean Return (%)')
ax6.set_facecolor(LIGHT_BG)
seasonal_chart_svg = fig_to_svg(fig6)
plt.close(fig6)

# 7. Momentum ROC
fig7, ax7 = plt.subplots(figsize=(14, 5))
ax7.plot(df['Date'], df['ROC_12M'] * 100, color=BLUE, linewidth=0.8, alpha=0.8, label='12M ROC')
ax7.plot(df['Date'], df['ROC_6M'] * 100, color=GREEN, linewidth=0.8, alpha=0.8, label='6M ROC')
ax7.plot(df['Date'], df['ROC_3M'] * 100, color=RED, linewidth=0.8, alpha=0.8, label='3M ROC')
ax7.axhline(y=0, color='black', linewidth=0.5)
ax7.set_title('Rate of Change (Momentum)', fontsize=14, fontweight='bold')
ax7.set_xlabel('Date')
ax7.set_ylabel('Rate of Change (%)')
ax7.legend(loc='upper left')
ax7.set_facecolor(LIGHT_BG)
momentum_chart_svg = fig_to_svg(fig7)
plt.close(fig7)

# 8. Volume vs Price Change
fig8, ax8 = plt.subplots(figsize=(12, 5))
high_vol_days = df[df['HighVolume']]
normal_days = df[~df['HighVolume']]
ax8.scatter(normal_days['AbsPriceChange'] * 100, normal_days['Volume'] / 1000,
            alpha=0.3, s=5, color=BLUE, label='Normal Volume')
ax8.scatter(high_vol_days['AbsPriceChange'] * 100, high_vol_days['Volume'] / 1000,
            alpha=0.5, s=10, color=RED, label='High Volume (>75th pct)')
ax8.set_title('Volume vs Absolute Price Change', fontsize=14, fontweight='bold')
ax8.set_xlabel('|Daily Price Change| (%)')
ax8.set_ylabel('Volume (thousands)')
ax8.legend()
ax8.set_facecolor(LIGHT_BG)
volume_chart_svg = fig_to_svg(fig8)
plt.close(fig8)

# 9. Volatility Time Series with Regimes
fig9, ax9 = plt.subplots(figsize=(14, 6))
ax9.fill_between(df['Date'], 0, df['RollingVol20'] * 100, alpha=0.3, color=BLUE, label='20-day Vol')
ax9.plot(df['Date'], df['RollingVol60'] * 100, color=DARK_BG, linewidth=1, label='60-day Vol')
ax9.axhline(y=annualized_vol * 100, color=RED, linestyle='--', linewidth=1.5,
           label=f'Overall Vol: {annualized_vol*100:.1f}%')
ax9.set_title('Volatility Time Series with Overall Average', fontsize=14, fontweight='bold')
ax9.set_xlabel('Date')
ax9.set_ylabel('Annualized Volatility (%)')
ax9.legend(loc='upper right')
ax9.set_facecolor(LIGHT_BG)
vol_timeseries_svg = fig_to_svg(fig9)
plt.close(fig9)

print("\n=== Visualizations generated ===")

# ============================================
# GENERATE HTML REPORT
# ============================================

html_content = f"""<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Gold Price Dynamics Report (2000-2025)</title>
    <style>
        :root {{
            --gold: #FFD700;
            --gold-dark: #B8860B;
            --bg-dark: #1a1a2e;
            --bg-light: #f8f9fa;
            --text-dark: #2d2d2d;
            --text-light: #f5f5f5;
            --blue: #2E86AB;
            --red: #E63946;
            --green: #2A9D8F;
        }}
        * {{ box-sizing: border-box; margin: 0; padding: 0; }}
        body {{
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            line-height: 1.6;
            color: var(--text-dark);
            background: linear-gradient(135deg, #0f0f1a 0%, #1a1a2e 100%);
            min-height: 100vh;
            padding: 20px;
        }}
        .container {{ max-width: 1400px; margin: 0 auto; }}
        .header {{
            background: linear-gradient(135deg, var(--gold-dark) 0%, var(--gold) 100%);
            color: var(--bg-dark);
            padding: 40px;
            border-radius: 16px;
            margin-bottom: 30px;
            text-align: center;
        }}
        .header h1 {{
            font-size: 2.5em;
            font-weight: 700;
            margin-bottom: 10px;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.2);
        }}
        .header p {{
            font-size: 1.1em;
            opacity: 0.9;
        }}
        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }}
        .kpi-card {{
            background: rgba(255,255,255,0.95);
            border-radius: 12px;
            padding: 25px;
            text-align: center;
            box-shadow: 0 10px 40px rgba(0,0,0,0.3);
            border-left: 4px solid var(--gold);
        }}
        .kpi-card h3 {{
            font-size: 0.9em;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: #666;
            margin-bottom: 10px;
        }}
        .kpi-card .value {{
            font-size: 2em;
            font-weight: 700;
            color: var(--bg-dark);
        }}
        .kpi-card .subtext {{
            font-size: 0.8em;
            color: #888;
            margin-top: 5px;
        }}
        .section {{
            background: rgba(255,255,255,0.95);
            border-radius: 16px;
            padding: 30px;
            margin-bottom: 25px;
            box-shadow: 0 10px 40px rgba(0,0,0,0.3);
        }}
        .section h2 {{
            font-size: 1.8em;
            color: var(--bg-dark);
