#!/usr/bin/env python3
"""
Gold Price Dynamics Report Generator
Analyzes gold price data from 2000-2025 and produces a comprehensive HTML report.
"""

import pandas as pd
import numpy as np
from datetime import datetime
import json

# Load and parse data
df = pd.read_csv('/app/benchmark/data.csv')
df['Date'] = pd.to_datetime(df['Date'], format='%d-%m-%y')

# Handle 2-digit year: 00-68 -> 2000-2068, 69-99 -> 1969-1999
# But since our data is 2000-2025, all should be 2000+
df.loc[df['Date'].dt.year > 2050, 'Date'] = df.loc[df['Date'].dt.year > 2050, 'Date'].apply(
    lambda x: x.replace(year=x.year - 100)
)

df = df.sort_values('Date').reset_index(drop=True)

# Round prices to 2 decimal places
for col in ['Open', 'High', 'Low', 'Close']:
    df[col] = df[col].round(2)

# Calculate daily log returns
df['LogReturn'] = np.log(df['Close'] / df['Close'].shift(1))

# Basic info
start_date = df['Date'].min()
end_date = df['Date'].max()
n_days = len(df)

print(f"Data loaded: {start_date.strftime('%Y-%m-%d')} to {end_date.strftime('%Y-%m-%d')}")
print(f"Total trading days: {n_days}")

# ============================================
# KPI CALCULATIONS
# ============================================

# 1. Annualized Return (CAGR)
first_close = df['Close'].iloc[0]
last_close = df['Close'].iloc[-1]
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = (last_close / first_close) ** (1/years) - 1

# 2. Annualized Volatility (std of log returns, annualized)
daily_vol = df['LogReturn'].std()
annualized_vol = daily_vol * np.sqrt(252)

# 3. Maximum Drawdown
cumulative = (1 + df['LogReturn'].fillna(0)).cumprod()
rolling_max = cumulative.cummax()
drawdown = (cumulative - rolling_max) / rolling_max
max_drawdown = drawdown.min()

# 4. Average Daily Volume (excluding early zero-volume period)
# Flag volume issues in early years
df['VolumeReliable'] = df['Volume'] > 0
reliable_volume_mean = df[df['Volume'] > 0]['Volume'].mean()

# 5. Sharpe-like Ratio (return / volatility, assuming rf=0)
sharpe_like = cagr / annualized_vol

print(f"\n=== KEY KPIs ===")
print(f"Annualized Return: {cagr:.2%}")
print(f"Annualized Volatility: {annualized_vol:.2%}")
print(f"Maximum Drawdown: {max_drawdown:.2%}")
print(f"Average Daily Volume (reliable): {reliable_volume_mean:,.0f}")
print(f"Sharpe-Like Ratio: {sharpe_like:.2f}")

# ============================================
# VOLATILITY REGIME DETECTION
# ============================================

# Calculate rolling volatility (20-day and 60-day)
df['RollingVol20'] = df['LogReturn'].rolling(window=20).std() * np.sqrt(252)
df['RollingVol60'] = df['LogReturn'].rolling(window=60).std() * np.sqrt(252)

# Define regimes based on percentiles of rolling volatility
vol_percentiles = df['RollingVol60'].dropna().quantile([0.33, 0.66])
low_vol_threshold = vol_percentiles[0.33]
high_vol_threshold = vol_percentiles[0.66]

def classify_regime(vol):
    if pd.isna(vol):
        return 'unknown'
    elif vol < low_vol_threshold:
        return 'low'
    elif vol > high_vol_threshold:
        return 'high'
    else:
        return 'medium'

df['VolRegime'] = df['RollingVol60'].apply(classify_regime)

# Identify crisis periods (extremely high volatility)
crisis_threshold = df['RollingVol60'].quantile(0.90)
df['Crisis'] = df['RollingVol60'] > crisis_threshold

# Crisis periods identified
crisis_periods = df[df['Crisis']]['Date'].tolist()
print(f"\nCrisis periods identified: {len(crisis_periods)} days with >90th percentile volatility")

# ============================================
