        }}
        .header p {{
            font-size: 1.1em;
            opacity: 0.9;
        }}
        .kpi-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }}
        .kpi-card {{
            background: rgba(255,255,255,0.95);
            border-radius: 12px;
            padding: 25px;
            text-align: center;
            box-shadow: 0 10px 40px rgba(0,0,0,0.3);
            border-left: 4px solid var(--gold);
        }}
        .kpi-card h3 {{
            font-size: 0.9em;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: #666;
            margin-bottom: 10px;
        }}
        .kpi-card .value {{
            font-size: 2em;
            font-weight: 700;
            color: var(--bg-dark);
        }}
        .kpi-card .subtext {{
            font-size: 0.8em;
            color: #888;
            margin-top: 5px;
        }}
        .section {{
            background: rgba(255,255,255,0.95);
            border-radius: 16px;
            padding: 30px;
            margin-bottom: 25px;
            box-shadow: 0 10px 40px rgba(0,0,0,0.3);
        }}
        .section h2 {{
            font-size: 1.8em;
            color: var(--bg-dark);
            border-bottom: 3px solid var(--gold);
            padding-bottom: 10px;
            margin-bottom: 20px;
        }}
        .section h3 {{
            font-size: 1.2em;
            color: var(--blue);
            margin: 20px 0 10px 0;
        }}
        .chart-container {{
            margin: 20px 0;
            text-align: center;
        }}
        .chart-container img {{
            max-width: 100%;
            height: auto;
            border-radius: 8px;
        }}
        .chart-caption {{
            font-size: 0.85em;
            color: #666;
            margin-top: 10px;
            font-style: italic;
        }}
        .stats-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 20px;
            margin: 20px 0;
        }}
        .stats-box {{
            background: var(--bg-light);
            border-radius: 8px;
            padding: 20px;
        }}
        .stats-box h4 {{
            color: var(--blue);
            margin-bottom: 10px;
            font-size: 1em;
        }}
        .stats-box ul {{
            list-style: none;
        }}
        .stats-box li {{
            padding: 5px 0;
            border-bottom: 1px solid #e0e0e0;
        }}
        .stats-box li:last-child {{
            border-bottom: none;
        }}
        .highlight {{
            background: linear-gradient(135deg, rgba(255,215,0,0.2), rgba(255,215,0,0.1));
            border-left: 4px solid var(--gold);
            padding: 15px 20px;
            margin: 15px 0;
            border-radius: 0 8px 8px 0;
        }}
        .regime-legend {{
            display: flex;
            justify-content: center;
            gap: 30px;
            margin: 15px 0;
            padding: 10px;
            background: var(--bg-light);
            border-radius: 8px;
        }}
        .regime-item {{
            display: flex;
            align-items: center;
            gap: 8px;
        }}
        .regime-dot {{
            width: 12px;
            height: 12px;
            border-radius: 50%;
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 15px 0;
        }}
        th, td {{
            padding: 12px;
            text-align: left;
            border-bottom: 1px solid #e0e0e0;
        }}
        th {{
            background: var(--blue);
            color: white;
            font-weight: 600;
        }}
        tr:nth-child(even) {{
            background: var(--bg-light);
        }}
        .methodology {{
            background: rgba(46, 134, 171, 0.1);
            border-radius: 8px;
            padding: 20px;
            margin: 15px 0;
        }}
        .methodology h4 {{
            color: var(--blue);
            margin-bottom: 10px;
        }}
        .methodology ul {{
            margin-left: 20px;
        }}
        .methodology li {{
            margin: 5px 0;
        }}
        .footer {{
            text-align: center;
            padding: 20px;
            color: var(--text-light);
            opacity: 0.7;
            font-size: 0.9em;
        }}
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>Gold Price Dynamics</h1>
            <p>Comprehensive Trend and Volatility Analysis (2000–2025)</p>
            <p style="margin-top: 10px; font-size: 0.9em;">Reporting Period: {start_date.strftime('%B %d, %Y')} – {end_date.strftime('%B %d, %Y')} | {n_days:,} Trading Days</p>
        </div>

        <!-- KPI Summary -->
