            <h3>Volume-Based Insights (Post-2003)</h3>
            <div class="stats-grid">
                <div class="stats-box">
                    <h4>High Volume Days</h4>
                    <ul>
                        <li>Count: <strong>{(df['HighVolume']).sum():,}</strong> days</li>
